<?php
 namespace QQWorld\Braintree\Test\Unit\Gateway\Request; use QQWorld\Braintree\Gateway\Helper\SubjectReader; use QQWorld\Braintree\Gateway\Request\VaultCaptureDataBuilder; use QQWorld\Payment\Gateway\Data\PaymentDataObjectInterface; use QQWorld\Sales\Api\Data\OrderPaymentExtension; use QQWorld\Sales\Model\Order\Payment; use QQWorld\Vault\Model\PaymentToken; class VaultCaptureDataBuilderTest extends \PHPUnit\Framework\TestCase { private $builder; private $paymentDO; private $payment; private $subjectReader; public function setUp() { $this->paymentDO = $this->createMock(PaymentDataObjectInterface::class); $this->payment = $this->getMockBuilder(Payment::class) ->disableOriginalConstructor() ->getMock(); $this->paymentDO->expects(static::once()) ->method('getPayment') ->willReturn($this->payment); $this->subjectReader = $this->getMockBuilder(SubjectReader::class) ->disableOriginalConstructor() ->getMock(); $this->builder = new VaultCaptureDataBuilder($this->subjectReader); } public function testBuild() { $amount = 30.00; $token = '5tfm4c'; $buildSubject = [ 'payment' => $this->paymentDO, 'amount' => $amount ]; $expected = [ 'amount' => $amount, 'paymentMethodToken' => $token ]; $this->subjectReader->expects(self::once()) ->method('readPayment') ->with($buildSubject) ->willReturn($this->paymentDO); $this->subjectReader->expects(self::once()) ->method('readAmount') ->with($buildSubject) ->willReturn($amount); $paymentExtension = $this->getMockBuilder(OrderPaymentExtension::class) ->setMethods(['getVaultPaymentToken']) ->disableOriginalConstructor() ->getMockForAbstractClass(); $paymentToken = $this->getMockBuilder(PaymentToken::class) ->disableOriginalConstructor() ->getMock(); $paymentExtension->expects(static::once()) ->method('getVaultPaymentToken') ->willReturn($paymentToken); $this->payment->expects(static::once()) ->method('getExtensionAttributes') ->willReturn($paymentExtension); $paymentToken->expects(static::once()) ->method('getGatewayToken') ->willReturn($token); $result = $this->builder->build($buildSubject); static::assertEquals($expected, $result); } } 